/**
 * Query defines the gRPC querier service.
 *
 * There is deliberately no endpoint that enumerates who owes whom. Every query
 * that returns obligations requires a participant, and the aggregate views
 * return totals rather than the bilateral matrix.
 *
 * That is friction, and it is described as friction rather than as
 * confidentiality, because a query handler is not a confidentiality mechanism:
 * a gRPC query carries no signature, so the chain does not know who is asking
 * and has nobody to authorise. Anyone who can run a node reads the state store
 * directly, and on a permissioned network every participant runs one. The
 * scoping that is real happens in two other places — the records that were
 * never written, since customer payments never reach this chain at all, and
 * the authenticated proxy in front of the REST gateway, which is the only
 * layer that knows who the caller is. See docs/guides/settlement.md.
 *
 * The shaping here still earns its place: an endpoint that exists gets indexed
 * by every explorer that meets it, and a graph that is technically public and
 * a graph that is published are not the same exposure.
 */
export interface Query {
  /** Params queries the parameters of the module. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** CurrentCycle queries the open netting window and when it closes. */
  CurrentCycle(request: QueryCurrentCycleRequest): Promise<QueryCurrentCycleResponse>;
  /** Cycle queries one window and what it settled, currency by currency. */
  Cycle(request: QueryCycleRequest): Promise<QueryCycleResponse>;
  /**
   * Position queries one participant's reserve, its committed part and its
   * running position in the open window.
   */
  Position(request: QueryPositionRequest): Promise<QueryPositionResponse>;
  /**
   * ParticipantObligations queries the obligations one participant is a party
   * to in one cycle, in either direction.
   */
  ParticipantObligations(request: QueryParticipantObligationsRequest): Promise<QueryParticipantObligationsResponse>;
  /**
   * HeldSlices queries every currency slice that failed to settle and is
   * waiting to be retried. It is the operational alarm: on a healthy chain it
   * is always empty, and anything in it is money that participants believe is
   * settled and is not.
   */
  HeldSlices(request: QueryHeldSlicesRequest): Promise<QueryHeldSlicesResponse>;
}

